SELECT 
FROM vi_owner_profile p JOIN vi_account a ON a.id = p.account_id
WHERE p.id = #{id}

SELECT COUNT(*) FROM vi_owner_profile p WHERE p.id = #{id}

    AND EXISTS (SELECT 1 FROM vi_order o WHERE o.owner_account_id = p.account_id
        AND o.dept_id IN #{d})

SELECT id, plate_no, vehicle_type_code, brand_model, vin_last4, verification_status, version
FROM vi_vehicle WHERE owner_account_id = #{accountId} AND deleted_at IS NULL
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}
